#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: ticket 32's live cutover. Eight stages.
#
# The cutover is THREE coupled changes (ADR 0004), and the third is the
# invisible one:
#
#   1. Render's PAYSTACK_SECRET_KEY -> live          (stage 5)
#   2. The live-mode Webhook URL set                 done 2026-09-28
#   3. plans.paystack_plan_code -> the live codes     (stage 6)
#
# Any two without the third breaks installment checkout. 1 and 3 must land in
# ONE SITTING, which is why they are adjacent here and why stage 7 re-reads
# both before this wizard will call itself finished.
#
# RESUME. Two mechanisms, and the split is deliberate:
#
#   1. By PROBE, for anything readable. `billing.accessOptions` is a PUBLIC
#      tRPC procedure returning is_active and paystack_plan_code for every
#      plan, so the state of change 3 is read from production rather than
#      remembered. No credential, no dashboard.
#   2. By STATE FILE, only for what nothing can read - Render's environment
#      is not queryable, so stage 5 is recorded rather than probed.
#
# That is the lesson tickets 28, 30 and 31 each paid hours for: read the
# setting, do not infer it. Where it cannot be read, say so.
#
# This wizard is SAFE TO RE-RUN. It re-probes, it offers to skip what is
# already done rather than skipping silently, and it moves no money.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

# Run from the repository root whatever directory it was invoked from, so
# ENV_FILE=.env means this project's .env.
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$REPO_ROOT"

PROD_URL="https://spellcode-by-aceify-two.vercel.app"
PLANS_ENDPOINT="$PROD_URL/api/trpc/billing.accessOptions"

# The reference that identifies the correct Paystack business. Ticket 30:
# dashboard URLs carry no business identifier, so no link can target one and
# the two businesses are similarly named. Data, not names.
FINGERPRINT="spellcode-963cdeab-a97c-40e4-8b2f-16a20889c376"

# This wizard's own state file, beside operator-remainder.sh's. Stage names
# and timestamps only: no values, no secrets.
STATE_FILE="docs/domain-model-alignment/.cutover-wizard.state"
# operator-remainder.sh's, read in stage 1 for its `checkout34` marker.
REMAINDER_STATE="docs/domain-model-alignment/.operator-remainder.state"

mark_done() { printf '%s\t%s\n' "$1" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" >> "$STATE_FILE"; }
is_done()   { [[ -f "$STATE_FILE" ]] && grep -qE "^${1}\b" "$STATE_FILE"; }

# offer_skip NAME "what it was" returns success when the human wants to skip a
# stage the state file says is done. It always OFFERS rather than skipping:
# a wizard that decides for you is how a stage gets quietly walked past, which
# is exactly what finish-switch-wizard.sh's stage 7 did.
offer_skip() {
  local name="$1" what="$2" when
  is_done "$name" || return 1
  when=$(grep -E "^${name}\b" "$STATE_FILE" | tail -n1 | cut -f2)
  note "This stage was recorded done at ${when}: $what"
  confirm "Skip it?" && return 0
  return 1
}

# plans_json fetches the public plan state from production.
plans_json() { curl -fsS --max-time 30 "$PLANS_ENDPOINT" 2>/dev/null; }

# plans_table prints one line per plan. Falls back to raw JSON without node.
plans_table() {
  local json
  json=$(plans_json) || { warn "could not read $PLANS_ENDPOINT"; return 1; }
  if command -v node >/dev/null 2>&1; then
    printf '%s' "$json" | node -e '
      let s = "";
      process.stdin.on("data", d => s += d).on("end", () => {
        try {
          for (const p of JSON.parse(s).result.data.json) {
            console.log("  " + p.code.padEnd(23) +
              " is_active=" + String(p.is_active).padEnd(6) +
              " paystack_plan_code=" + (p.paystack_plan_code ?? "null"));
          }
        } catch (e) { console.log("  could not parse the plan response: " + e.message); }
      });'
  else
    note "node not found, so here is the raw response:"
    printf '  %s\n' "$json"
  fi
}

# installments_configured succeeds only when BOTH installment plans carry a
# PLN_ code and are active. This is the whole definition of "change 3 landed".
installments_configured() {
  local json
  json=$(plans_json) || return 1
  command -v node >/dev/null 2>&1 || return 1
  printf '%s' "$json" | node -e '
    let s = "";
    process.stdin.on("data", d => s += d).on("end", () => {
      try {
        const rows = JSON.parse(s).result.data.json;
        const want = ["full-access-3-month", "full-access-6-month"];
        const ok = want.every(code => {
          const p = rows.find(r => r.code === code);
          return p && p.is_active === true && typeof p.paystack_plan_code === "string" &&
                 p.paystack_plan_code.startsWith("PLN_");
        });
        process.exit(ok ? 0 : 1);
      } catch { process.exit(1); }
    });' >/dev/null 2>&1
}

# ask_plan_code KEY "Prompt" keeps asking until the answer looks like a
# Paystack plan code. A wrong-mode or mistyped code fails at Paystack for
# change 1's path and SILENTLY for the two incoming lookups, so this is the
# cheapest place to catch it.
ask_plan_code() {
  local key="$1" prompt="$2" value=""
  while true; do
    ask "$key" "$prompt"
    value="${!key}"
    [[ "$value" == PLN_* ]] && break
    warn "A Paystack plan code starts with PLN_. Got: ${value:-(empty)}"
  done
}

banner "Ticket 32: the live cutover"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "The gate: stage 7's success path"

say "ADR 0004 ends test-mode checkout against production:"
printf '\n'
note "  \"There is no third option where they are tested with a test card"
note "   against production.\""
printf '\n'
say "So the live-money path becomes the ONLY way to exercise checkout after"
say "this wizard runs. That is one-way in practice, and it is why the"
say "cutover must not precede a checkout proved end to end in test mode."
printf '\n'
say "The proof is operator-remainder.sh stage 7: a post-ticket-34 checkout"
say "that completed, read back from the database as a payment at success and"
say "a subscription at active. It records itself as 'checkout34'."
printf '\n'

if [[ -f "$REMAINDER_STATE" ]] && grep -qE '^checkout34\b' "$REMAINDER_STATE"; then
  WHEN=$(grep -E '^checkout34\b' "$REMAINDER_STATE" | tail -n1 | cut -f2)
  printf '  %s✓%s operator-remainder.sh recorded checkout34 at %s\n' "$GREEN" "$RESET" "$WHEN"
  printf '\n'
  warn "That record is a human's confirmation of a database reading, not a"
  note "  second measurement. If you do not remember making it, stop and"
  note "  re-read the rows before trusting it."
  if ! confirm "Proceed with the cutover?"; then
    warn "Stopping, nothing changed."
    exit 0
  fi
else
  printf '  %s✗%s No checkout34 marker in %s\n' "$RED" "$RESET" "$REMAINDER_STATE"
  printf '\n'
  warn "REFUSING TO CONTINUE. Stage 7's success path is not proved."
  printf '\n'
  say "What to do instead, in order:"
  step "Run: bash docs/domain-model-alignment/operator-remainder.sh"
  step "Take its stage 7 - a test-mode checkout on a THIRD test Learner."
  note "  A third, because the stage 10 account holds an active Subscription"
  note "  and ticket 34's access guard correctly refuses it a new checkout."
  step "Then re-run this wizard."
  printf '\n'
  note "This refusal is the wizard doing its job. Do not work around it by"
  note "editing the state file: the marker is a record of a reading, and"
  note "writing one by hand makes it a lie about production billing."
  exit 1
fi

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Read where the cutover actually stands"

say "Production, read from the public plan endpoint rather than remembered:"
printf '\n'
open_url "$PLANS_ENDPOINT"
plans_table || true
printf '\n'
say "What each line means:"
note "  full-access-one-time  - interval one_time, never sends a plan code."
note "    Its null code has cost nothing and is not part of this cutover."
note "  the two installment plans - these are the cutover. A PLN_ code AND"
note "    is_active true, or they are unsellable."
printf '\n'

if installments_configured; then
  printf '  %s✓%s Both installment plans already carry a PLN_ code and are active.\n' "$GREEN" "$RESET"
  printf '\n'
  warn "This wizard may have already been run, or change 3 was applied by hand."
  say "Change 1 - Render's key - is NOT readable from here, so it is the one"
  say "to check by eye. Stage 5 will ask."
  printf '\n'
  if ! confirm "Continue anyway?"; then
    warn "Stopping, nothing changed."
    exit 0
  fi
else
  note "Change 3 has not landed: at least one installment plan is missing a"
  note "PLN_ code or is inactive. That matches a pre-cutover world."
fi
pause "Ready for the business check?"

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Establish WHICH Paystack business you are in"

warn "The project owner has two Paystack businesses, and they are similarly"
note "  named. Dashboard URLs carry no business identifier - everything after"
note "  the # is a client-side route - so NO LINK CAN TARGET A BUSINESS,"
note "  including the one below. Paystack shows whichever the session last"
note "  selected; the switcher is at the top left (ticket 30)."
printf '\n'
say "Tell them apart by data. The correct business is the one whose"
say "transaction list contains this reference:"
printf '\n'
printf '  %s%s%s\n' "$BOLD" "$FINGERPRINT" "$RESET"
printf '\n'
note "That is the 2026-09-27 test-mode charge that proved the payment path."
note "A ticket-30 orphan of 120,000 sits on the OTHER business, which is how"
note "this went unnoticed for three days."
printf '\n'
open_url "https://dashboard.paystack.com/#/transactions"
step "Switch to TEST mode to see that reference, since the charge was a test."
step "Search the transaction list for the reference above."
printf '\n'
say "Test and live are two modes of ONE business, so identifying the"
say "business in test mode carries to its live mode. That is why the"
say "live webhook could be set on 2026-09-28 from a test-mode check."
printf '\n'

if ! confirm "Did you find that reference on the business you are signed into?"; then
  warn "STOPPING. Everything below writes live payment configuration, and on"
  note "  the wrong business it fails exactly the way ticket 28 did - except"
  note "  with real money and no test card to prove it."
  say "Use the switcher at the top left, then re-run this wizard."
  exit 1
fi
printf '  %s✓%s Business confirmed by data rather than by name.\n' "$GREEN" "$RESET"
pause "Ready to read the live plan codes?"

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Capture both live PLN_ codes"

say "A Paystack plan object exists in exactly ONE mode. The same plan made"
say "in test and in live has two different PLN_ codes, and"
say "plans.paystack_plan_code is one column with no mode dimension."
printf '\n'
say "The plan objects were created in live mode on 2026-09-28 and their"
say "codes have never been written down. That is ticket 32's first open box,"
say "and this stage closes it."
printf '\n'
open_url "https://dashboard.paystack.com/#/plans"
step "Switch the dashboard to LIVE mode. The toggle is top right."
step "Open the 3-month Full Access plan and copy its plan code (PLN_...)."
printf '\n'
ask_plan_code PAYSTACK_LIVE_PLAN_CODE_3MONTH "Paste the 3-month live plan code:"
step "Go back, open the 6-month plan, and copy its plan code."
ask_plan_code PAYSTACK_LIVE_PLAN_CODE_6MONTH "Paste the 6-month live plan code:"
printf '\n'

if [[ "$PAYSTACK_LIVE_PLAN_CODE_3MONTH" == "$PAYSTACK_LIVE_PLAN_CODE_6MONTH" ]]; then
  warn "Those are the same code. Two plans cannot share one PLN_ code."
  say "Re-run this stage and read each plan's own code."
  exit 1
fi

# PLN_ codes are public identifiers, so .env is a convenience rather than a
# secret store. The gitignore check runs anyway: this file holds the service
# role key already, and a wizard that writes to a tracked .env is a mistake
# worth refusing on a day it happens to be harmless.
if command -v git >/dev/null 2>&1 && ! git check-ignore -q "$ENV_FILE" 2>/dev/null; then
  warn "$ENV_FILE is NOT gitignored. Not writing to it."
  SKIPPED+=("record both PLN_ codes by hand: $ENV_FILE is tracked")
else
  write_env PAYSTACK_LIVE_PLAN_CODE_3MONTH "$PAYSTACK_LIVE_PLAN_CODE_3MONTH"
  write_env PAYSTACK_LIVE_PLAN_CODE_6MONTH "$PAYSTACK_LIVE_PLAN_CODE_6MONTH"
  note "Recorded locally. Stage 8 prints them for ticket 32, because .env"
  note "travels with this machine and the ticket travels with the repository."
fi
pause "Ready for change 1 of 3?"

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Change 1 of 3: Render's Paystack keys -> live"

if ! offer_skip render_live_key "Render was recorded as holding the live secret key"; then
  warn "FROM HERE, ONE SITTING. Between this stage and the next, Render is in"
  note "  live mode while the database still holds no live plan codes, so"
  note "  installment checkout is broken in that window. One-time checkout is"
  note "  unaffected - it never sends a plan code - so the blast radius is"
  note "  installments only. Do not stop in the middle."
  printf '\n'
  open_url "https://dashboard.render.com/"
  step "Open the spellcode-backend service, then Environment."
  step "Set PAYSTACK_SECRET_KEY to the LIVE secret key (sk_live_...)."
  note "  Read it from Paystack: Settings -> API Keys & Webhooks, in LIVE mode."
  step "Set PAYSTACK_PUBLIC_KEY to the live public key (pk_live_...)."
  printf '\n'
  note "About that second one: nothing in this codebase reads it. It is"
  note "loaded into ENV.paystackPublicKey and used by no module - checkout is"
  note "initialized server-side and the browser only follows the"
  note "authorization_url. Set it for consistency; expect no behaviour change."
  printf '\n'
  warn "Do NOT put the live secret key in this machine's .env. Local runs"
  note "  would then move real money, which is the circumstance ADR 0004"
  note "  exists to remove. This wizard deliberately does not ask for it."
  printf '\n'
  step "Save. Render auto-deploys on its own - established 2026-10-03 by"
  step "reading /api/version twice - but an environment change restarts the"
  step "service, so give it a minute."
  printf '\n'

  if confirm "Is PAYSTACK_SECRET_KEY now the live key in Render?"; then
    mark_done render_live_key
    printf '  %s✓%s Change 1 recorded. It cannot be probed, so this record is it.\n' "$GREEN" "$RESET"
  else
    warn "STOPPING with change 1 not made. Nothing is half-done: the database"
    note "  still has no live plan codes, so the system is consistent in test"
    note "  mode. Re-run when you can finish both changes together."
    SKIPPED+=("ticket 32 change 1: Render's PAYSTACK_SECRET_KEY -> live")
    exit 1
  fi
fi
pause "Straight on to change 3, now, in this sitting."

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Change 3 of 3: patch the plan codes"

say "There is a UI for this and it needs no SQL: /admin has a Paystack plan"
say "code field per plan, wired to billing.updatePlan."
printf '\n'
note "It requires a Supabase profile whose role is 'admin'. Without one the"
note "page says so rather than failing oddly."
printf '\n'
open_url "$PROD_URL/admin"
step "Sign in as an admin, then find the Access plans table."
printf '\n'
say "For Full Access (3-Month Installment):"
step "  Paystack plan code -> $PAYSTACK_LIVE_PLAN_CODE_3MONTH"
step "  Click the Inactive button so it reads Active."
step "  Click Save. Expect the toast 'Plan saved.'"
printf '\n'
say "For Full Access (6-Month Installment):"
step "  Paystack plan code -> $PAYSTACK_LIVE_PLAN_CODE_6MONTH"
step "  Click the Inactive button so it reads Active."
step "  Click Save."
printf '\n'
note "Leave the Amount fields alone unless the price is changing: Save sends"
note "amount, code and active together, so whatever is in the box is written."
note "Leave full-access-one-time alone entirely - it needs no plan code."
printf '\n'
pause "Saved both plans?"

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "Verify, by reading production again"

say "The same public endpoint as stage 2. This is the measurement, not the"
say "toast you just saw."
printf '\n'
plans_table || true
printf '\n'

if installments_configured; then
  printf '  %s✓ Change 3 has landed%s: both installment plans carry a PLN_ code\n' "$GREEN" "$RESET"
  printf '    and are active.\n'
  mark_done plan_codes_live
  printf '\n'
  say "What this does NOT prove: that the codes are the LIVE ones rather than"
  say "a pair of well-formed strings. Nothing readable from here can tell"
  say "those apart - the repository holds test keys, and Paystack's /plan"
  say "endpoint only returns the plans of its own key's mode. The live-money"
  say "test on the launch checklist is what settles it."
  printf '\n'
  note "One good consequence of ticket 32's engineering half: a webhook whose"
  note "plan lookup misses now THROWS, so it lands in processing_error and in"
  note "Paystack's own webhook log instead of being marked processed. And"
  note "because Paystack retries a non-200, any renewal that failed while the"
  note "column was null self-heals on its next retry now that it is not."
else
  warn "Change 3 did NOT land. At least one installment plan still has no"
  note "  PLN_ code or is still inactive."
  printf '\n'
  warn "You are now in the dangerous window: Render on live keys, database"
  note "  without live plan codes. Installment checkout fails on"
  note "  \"This installment plan is not configured yet.\" One-time checkout"
  note "  still works."
  printf '\n'
  say "Go back to $PROD_URL/admin and save both plans, then re-run this"
  say "wizard - it will skip what is already done."
  SKIPPED+=("ticket 32 change 3: plans.paystack_plan_code -> the live codes")
fi
pause "Ready for the last stage?"

# ── Stage 8 ───────────────────────────────────────────────────────────────
stage "Record it where it survives this machine"

say "Ticket 32's first box asks for the live plan codes to be durable, so a"
say "cutover never again depends on someone reopening the dashboard. Paste"
say "this into docs/domain-model-alignment/issues/32-plan-codes-are-per-mode-and-the-column-is-not.md:"
printf '\n'
printf '%s' "$DIM"
cat <<PASTE
  ### Live plan codes, captured $(date -u +%Y-%m-%d)

  | plan | live PLN_ code |
  |---|---|
  | \`full-access-3-month\` | \`$PAYSTACK_LIVE_PLAN_CODE_3MONTH\` |
  | \`full-access-6-month\` | \`$PAYSTACK_LIVE_PLAN_CODE_6MONTH\` |

  Read from the Paystack dashboard in live mode, on the business carrying
  \`$FINGERPRINT\`.
  These are public identifiers; no key is recorded.
PASTE
printf '%s' "$RESET"
printf '\n'
note "PLN_ codes are public identifiers, which is why they belong in a"
note "tracked ticket rather than only in .env."
printf '\n'
say "Still open after this wizard, deliberately:"
step "A live-money Paystack test, with Render on live keys and the live"
step "webhook. Until that runs, the codes above are unproven."
step "Exclude the stage 10 test Subscription from any revenue figure. It is"
step "an active Subscription won with a test card; payment_transactions has"
step "no mode column, so the exclusion is by user_id, by hand (ADR 0004)."
printf '\n'
note "And if you got here having decided NOT to switch installments on,"
note "record that as withheld in ticket 32's last box. Either is a"
note "legitimate close; leaving the box silent is not."

finish
